pub fn get_glyph(c: char) -> Option<&'static [u16; 16]> {
    for glyph in CHINESE_FONTS {
        if glyph.c == c {
            return Some(&glyph.rows);
        }
    }
    None
}

pub fn draw_chinese_str<D>(target: &mut D, mut x: i32, y: i32, text: &str, color: Rgb565)
where
    D: DrawTarget<Color = Rgb565>,
{
    for c in text.chars() {
        if let Some(rows) = get_glyph(c) {
            for (row_idx, &row_val) in rows.iter().enumerate() {
                for col_idx in 0..16 {
                    if (row_val & (1 << (15 - col_idx))) != 0 {
                        let _ = Pixel(Point::new(x + col_idx as i32, y + row_idx as i32), color).draw(target);
                    }
                }
            }
            x += 17;
        } else {
            // ASCII characters
            x += 8;
        }
    }
}
